size_t dk1_scene_recipe_count(void){return DK1_SCENE_RECIPE_COUNT;}
bool dk1_scene_recipe_for_callback(uint16_t cb,Dk1SceneRecipe*out){size_t i;if(!out)return false;for(i=0;i<DK1_SCENE_RECIPE_COUNT;i++)if(R[i].init_callback_b9==cb){*out=R[i];return true;}return false;}
bool dk1_scene_recipe_for_level(const Dk1RomImage*rom,uint16_t level,Dk1SceneRecipe*out){uint16_t cb=0;if(!rom||!out||level>=DK1_SCENE_LEVEL_COUNT||!dk1_rom_read_u16(rom,0xB9801Eu+(uint32_t)level*2u,&cb))return false;return dk1_scene_recipe_for_callback(cb,out);}
